#include <bits/stdc++.h>
using namespace std;

using ll = long long;

ll sol(ll x) {
    ll out = x;
    while (x > 0) {
        out -= x % 10;
        x /= 10;
    }
    return out;
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    ll n, s;
    cin >> n >> s;

    ll lo = 1, hi = n + 1;
    while (lo < hi) {
        ll mid = lo + (hi - lo) / 2;
        if (sol(mid) < s)
            lo = mid + 1;
        else
            hi = mid;
    }

    cout << n - lo + 1 << '\n';
    return 0;
}

